// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length == v.length && _tos.length > 0);
        // bound v[i] to avoid overflow (as in require)
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, bytes memory returnData) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        if (success) {
            bool result = abi.decode(returnData, (bool));
            assertTrue(result, "transfer should return true when it succeeds");
        }
    }
}

